mapper.select:
SELECT a.created_at, u.nickname, u.real_name, u.mobile, u.wechat_id,
       a.media_type, a.external_account_id, a.account_name, a.account_link,
       COALESCE(f.status, 'NOT_SUBMITTED') AS filing_status, p.provider_name
FROM promotion_media_account a
JOIN promotion_user u ON u.id = a.user_id
LEFT JOIN provider_media_filing f ON f.media_account_id = a.id
LEFT JOIN short_drama_connection c ON c.id = f.connection_id
LEFT JOIN short_drama_provider p ON p.id = c.provider_id
WHERE 1 = 1

    AND u.user_no = #{query.userNo}


    AND a.media_type = #{query.mediaType}


    AND a.status = #{query.accountStatus}


    AND c.provider_id = #{query.providerId}


    AND f.filing_method = #{query.filingMethod}




            AND (f.status = 'NOT_SUBMITTED' OR f.id IS NULL)


            AND f.status = #{query.filingStatus}



ORDER BY a.id DESC, f.id ASC
